wdd.addEventListener('click',e=>{const b=e.target.closest('[data-w]');if(b){if(b.dataset.w==='demo'||b.dataset.w==='real'){wdd.classList.remove('on');return b.dataset.w==='demo'?ZR.disconnect():needWallet()}if(Z.REAL&&b.dataset.w==='dc'){return ZR.disconnect()}if(b.dataset.w==='eye'){if(Z.REAL&&!S.eye&&!S.balKnown){wdd.classList.remove('on');return window.ZR&&ZR.decryptBalance()}S.eye=!S.eye;Z.save();navUI();wddR();render();return}S.conn=false;Z.save();navUI();toast('Disconnected')}wdd.classList.remove('on')});
